const AccountSettingsSchema = z
  .strictObject({
    backups_enabled: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          'Account-wide backups default.  If `true`, all Linodes created will automatically be enrolled in the Backups service.  If `false`, Linodes will not be enrolled by default, but may still be enrolled on creation or later.',
        example: true,
        'x-linode-cli-display': 4,
      }),
    interfaces_for_new_linodes: z
      .enum([
        'legacy_config_only',
        'legacy_config_default_but_linode_allowed',
        'linode_default_but_legacy_config_allowed',
        'linode_only',
      ])
      .exactOptional()
      .openapi({
        description:
          "__Beta__ Defines if new Linodes can use legacy configuration interfaces:\n- `legacy_config_only`. All new Linodes need to use legacy configuration interfaces. Prevously created Linodes with Linode Interfaces can still exist. Linodes using legacy configuration interfaces can't be upgraded to use Linode Interfaces.\n- `legacy_config_default_but_linode_allowed`. New Linodes can use legacy configuration interfaces or Linode Interfaces, depending on the `interface_generation` setting specified when creating the Linode. By default, new Linodes use legacy configuration interfaces unless otherwise specified. Linodes that use legacy configuration interfaces can upgrade to Linode Interfaces. This is the default setting for existing accounts.\n- `linode_default_but_legacy_config_allowed`. New Linodes can use legacy configuration interfaces or Linode Interfaces, depending on the `interface_generation` setting specified when creating the Linode. By default, new Linodes use Linode Interfaces unless otherwise specified. Linodes that use legacy configuration interfaces can upgrade to Linode interfaces. This is the default setting for new accounts.\n- `linode_only`. All new Linodes need to use Linode Interfaces. Prevously created Linodes with legacy configuration profile interfaces can still exist if they were created under a previous setting. Linodes using legacy configuration interfaces can be upgraded to Linode Interfaces.",
        example: 'linode_only',
        'x-akamai': { status: 'BETA' },
        'x-linode-cli-display': 6,
      }),
    longview_subscription: z
      .string()
      .exactOptional()
      .openapi({
        description:
          '__Read-only__ The Longview Pro tier you are currently subscribed to. The value must be a [Longview subscription](https://techdocs.akamai.com/linode-api/reference/get-longview-subscriptions) ID or `null` for Longview Free.',
        example: 'longview-3',
        readOnly: true,
        'x-linode-cli-display': 2,
      }),
    maintenance_policy: z
      .enum(['linode/migrate', 'linode/power_off_on'])
      .exactOptional()
      .openapi({
        description:
          '__Beta__ Defines the default maintenance policy for new Linodes created on this account. Review [maintenance policy](https://techdocs.akamai.com/cloud-computing/docs/host-maintenance-policy) documentation for more details.',
        example: 'linode/migrate',
        'x-akamai': { status: 'BETA' },
        'x-linode-cli-display': 7,
      }),
    managed: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          "__Read-only__ Our 24/7 incident response service. This robust, multi-homed monitoring system distributes monitoring checks to ensure that your servers remain online and available at all times. Linode Managed can monitor any service or software stack reachable over TCP or HTTP. Once you add a service to Linode Managed, we'll monitor it for connectivity, response, and total request time.",
        example: true,
        readOnly: true,
        'x-linode-cli-display': 3,
      }),
    network_helper: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          'Enables network helper across all users by default for new Linodes and Linode Configs.',
        example: false,
        'x-linode-cli-display': 1,
      }),
    object_storage: z
      .enum(['disabled', 'suspended', 'active'])
      .default('disabled')
      .exactOptional()
      .openapi({
        description:
          "__Read-only__ A string describing the status of this account's Object Storage service enrollment.",
        example: 'active',
        readOnly: true,
        'x-linode-cli-display': 5,
      }),
  })
  .openapi({
    description: 'Account Settings object.',
    'x-akamai': { 'file-path': 'schemas/account-settings.yaml' },
    required: [],
  })
  .openapi('AccountSettings')

