export const deleteApiVersionLinodeInstancesLinodeIdConfigsConfigIdRoute = createRoute({
  method: 'delete',
  path: '/{apiVersion}/linode/instances/{linodeId}/configs/{configId}',
  tags: ['Configuration profiles'],
  summary: 'Delete a configuration profile',
  description:
    'Deletes the specified configuration profile from the specified Linode.\n\n\n<<LB>>\n\n---\n\n\n- __CLI__.\n\n    ```\n    linode-cli linodes config-delete 123 23456\n    ```\n\n    [Learn more...](https://techdocs.akamai.com/cloud-computing/docs/getting-started-with-the-linode-cli)\n\n- __OAuth scopes__.\n\n    ```\n    linodes:read_write\n    ```\n\n    [Learn more...](https://techdocs.akamai.com/linode-api/reference/get-started#oauth)',
  externalDocs: {
    description: "See documentation for this operation in Akamai's Linode API",
    url: 'https://techdocs.akamai.com/linode-api/reference/delete-linode-config',
  },
  operationId: 'delete-linode-config',
  request: {
    params: z.object({
      apiVersion: z
        .enum(['v4', 'v4beta'])
        .openapi({
          param: {
            description:
              '__Enum__ Call either the `v4` URL, or `v4beta` for operations still in Beta.',
            example: '{{apiVersion}}',
            in: 'path',
            name: 'apiVersion',
            required: true,
            schema: { enum: ['v4', 'v4beta'], type: 'string' },
            'x-akamai': { 'file-path': 'parameters/api-version-path.yaml' },
          },
        }),
      linodeId: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .openapi({
          param: {
            description: 'The `id` of the Linode.',
            example: '{{linodeId}}',
            in: 'path',
            name: 'linodeId',
            required: true,
            schema: { example: 234, type: 'integer' },
            'x-akamai': { 'file-path': 'parameters/linode-id.yaml' },
          },
          example: 234,
        }),
      configId: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .openapi({
          param: {
            description: 'The `id` of the Configuration Profile.',
            example: '{{configId}}',
            in: 'path',
            name: 'configId',
            required: true,
            schema: { example: 521, type: 'integer' },
            'x-akamai': { 'file-path': 'parameters/config-id-profile.yaml' },
          },
          example: 521,
        }),
    }),
  },
  responses: {
    200: {
      description: 'Configuration profile successfully deleted.',
      content: {
        'application/json': {
          schema: z
            .object({})
            .refine((val) => Object.keys(val).length <= 0)
            .openapi({
              description: 'The API responds with an empty object.',
              'x-akamai': { 'file-path': 'schemas/added-empty-obj.yaml' },
            }),
        },
      },
    },
    default: {
      description:
        'See [Errors](https://techdocs.akamai.com/linode-api/reference/errors) for the range of possible error response codes.',
      content: {
        'application/json': {
          schema: z
            .strictObject({
              errors: z
                .array(
                  z
                    .strictObject({
                      field: z
                        .string()
                        .exactOptional()
                        .openapi({
                          description:
                            'The field in the request that caused this error. This may be a path, separated by periods in the case of nested fields. In some cases this may come back as `null` if the error is not specific to any single element of the request.',
                          example: 'fieldname',
                        }),
                      reason: z
                        .string()
                        .exactOptional()
                        .openapi({
                          description:
                            'What happened to cause this error. In most cases, this can be fixed immediately by changing the data you sent in the request, but in some cases you will be instructed to [Open a support ticket](https://techdocs.akamai.com/linode-api/reference/post-ticket) or perform some other action before you can complete the request successfully.',
                          example: 'fieldname must be a valid value',
                        }),
                    })
                    .openapi({
                      description:
                        'An object for describing a single error that occurred during the processing of a request.',
                      'x-akamai': { 'file-path': 'schemas/error-object.yaml' },
                      required: [],
                    }),
                )
                .exactOptional(),
            })
            .openapi({ required: [] }),
        },
      },
    },
  },
  security: [{ personalAccessToken: [] }, { oauth: ['linodes:read_write'] }],
})

